contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint putAmount, uint lockTime, uint minSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount);

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Put{value: putAmount}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;
        uint testContractBalanceBefore = address(this).balance;

        bool reverted;

        c.Collect(collectAmount); if (__ESBMC_reverted()) return;
        reverted = false;

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        bool precondition = (balanceBefore >= minSum && balanceBefore >= collectAmount && block.timestamp > unlockTimeBefore);

        assert((precondition && balanceAfter == balanceBefore - collectAmount) || (!precondition && balanceAfter == balanceBefore && !reverted));
    }

    receive() external payable {}
}

