pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 putAmount, uint256 lockTime, uint256 minSum, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Put{value: putAmount}(lockTime) {} catch { return; }
        uint256 unlockTimeBefore;
        uint256 balanceBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeBefore = __r0; balanceBefore = __r1; } catch { return; }
        uint contractBalanceBefore = address(c).balance;
        uint testContractBalanceBefore = address(this).balance;
        bool reverted;
        try c.Collect(collectAmount) {} catch { return; }
        reverted = false;
        uint256 unlockTimeAfter;
        uint256 balanceAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeAfter = __r0; balanceAfter = __r1; } catch { return; }
        bool precondition = (balanceBefore >= minSum && balanceBefore >= collectAmount && block.timestamp > unlockTimeBefore);
        assertTrue((precondition && balanceAfter == balanceBefore - collectAmount) || (!precondition && balanceAfter == balanceBefore && !reverted));
    }

    function testFuzz_run(uint256 putAmount, uint256 lockTime, uint256 minSum, uint256 collectAmount) public {
        _run(putAmount, lockTime, minSum, collectAmount);
    }

    receive() external payable {}
